nginx_config:
daemon off;
master_process on;
worker_processes 8;
pid /tmp/aegisx-nginx-l9rt4657/nginx.pid;
error_log /tmp/aegisx-nginx-l9rt4657/nginx-error.log crit;
events { worker_connections 16384; multi_accept on; }
http {
    access_log off;
    client_body_temp_path /tmp/aegisx-nginx-l9rt4657/body;
    proxy_temp_path /tmp/aegisx-nginx-l9rt4657/proxy;
    keepalive_timeout 60s;
    keepalive_requests 100000;
    upstream origin { server 127.0.0.1:55627; keepalive 256; }
    server {
        listen 127.0.0.1:58935 reuseport;
        location / {
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            proxy_set_header Host 127.0.0.1:55627;
            proxy_request_buffering off;
            proxy_buffering off;
            proxy_pass http://origin;
        }
    }
}

aegisx_config:
set_listen("127.0.0.1:36029")
set_upstream("127.0.0.1:55627")
set_store(false)
set_model {mode="off"}
set_runtime {threads=8,max_in_flight=16384,write_buffer_bytes=4096,upstream_keepalive_capacity=256}
set_cache {decisions=false,responses=false}
set_limits {rate_limit_10s=0}
